changeSet.sql:
CREATE TABLE announcement_timetable_assignment (
    announcement_id BIGINT NOT NULL REFERENCES announcement(id) ON DELETE CASCADE,
    timetable_id BIGINT NOT NULL REFERENCES timetable(id) ON DELETE RESTRICT,
    CONSTRAINT pk_announcement_timetable_assignment PRIMARY KEY (announcement_id, timetable_id)
);
CREATE INDEX idx_announcement_timetable_assignment_timetable
    ON announcement_timetable_assignment(timetable_id);
ALTER TABLE announcement
    ADD CONSTRAINT chk_announcement_target_scope CHECK (target_scope IN ('CLASS','SUBJECT'));
ALTER TABLE announcement
    ADD CONSTRAINT chk_announcement_subject_target
    CHECK (target_scope <> 'SUBJECT' OR audience_type = 'CLASS');
